## illustration of dirichlet distribution
## first example is dirichlet(1,1,1)

# draw dirichlet samplesrdirichlet <- function(n, alpha) {  y <- matrix(rgamma(3*n, shape = alpha), ncol = 3, byrow = TRUE)  y / rowSums(y)}# the the value of alpha# and draw from the dirichletalpha <- c(1, 1, 1)n <- 2000samples <- rdirichlet(n, alpha)# convert simplex coordinates to 2Dto_xy <- function(theta) {  x <- theta[,2] + 0.5 * theta[,3]  y <- (sqrt(3)/2) * theta[,3]  cbind(x, y)}coords <- to_xy(samples)# create a simple plotting functionplot(NA, xlim=c(0,1), ylim=c(0, sqrt(3)/2),     xlab="", ylab="", axes=FALSE, asp=1)# triangle outlinepolygon(  x = c(0, 1, 0.5),  y = c(0, 0, sqrt(3)/2),  border = "black")# label the theta values (in the corners)text(0, 0,     expression(theta[1]), pos=1)text(1, 0,     expression(theta[2]), pos=1)text(0.5, sqrt(3)/2, expression(theta[3]), pos=3)# label the points in bluepoints(coords, pch=16, cex=0.6, col="blue")